    "0352bdc4": {"text":"20) return { ok:false, raison:'long' } ; if (!houseNameCharsOk(nm)) return { ok:false, Reason:'chars' }; return { ok:true, nom:nm} ; } ; /* Une maison est simplement la chaîne c.dyn que partagent ses membres, donc un changement de nom réécrit chaque caractère portant l'ancienne chaîne — la même règle d'appartenance utilisée par FB.dynastyNameSet — plus l'identité du royaume du joueur lorsqu'elle a été dérivée de la maison. Les noms et prénoms personnels restent intacts, et le texte de la chronique ou de la légende déjà écrit conserve l'ancien nom. L'héraldique est issue de la chaîne dyn, donc les armoiries sont redessinées. */ FB.renameHouse = function (state, newName) { const me = state && state.player && state.chars && state.chars[state.player.charId]; if (!me || !me.dyn) return { ok:false, Reason:'nohouse' }; const oldDyn = me.dyn; const check = FB.validateHouseName(newName, oldDyn); if (!check.ok) renvoie le chèque ; const nm = check.name; pour (const id dans state.chars) { const c = state.chars[id]; si (c && c.dyn === oldDyn) c.dyn = nm; } const realm = state.realms && state.realms.player; if (domaine) { if (realm.name === 'Royaume de ' + oldDyn) realm.name = 'Royaume de ' + nm; si (realm.dynasty === oldDyn) realm.dynasty = nm; } FB.touchFamily(); FB.news(state, FB.msg('news.house.renamed', '👑 La maison de {old} est désormais connue sous le nom de {dynasty}.', { old:oldDyn, dynasty:nm })); return { ok:true, nom:nm, old:oldDyn } ; } ; /* ---------- fabrique de caractères ---------- opts: {sex, culture, religion, born, dyn, role, quality (skill bonus), traitsN} opts.id installe une identité dérivée de l'appelant au lieu de dessiner le prochain uid séquentiel. Les archives judiciaires l'utilisent pour que le même membre de la succession se résolve toujours avec le même identifiant de personnage, qu'il ait été créé lors de la création du monde ou au moment où un joueur a ouvert le royaume pour la première fois. */ FB.makeCharacter = function (état, opts) { const sex = opts.sex || (FB.chance(0.5) ? 'm' : 'f'); const c = { identifiant : opts.id || FB.uid(), nom : opts.name || FB.randomName(opts.culture, sex, opts.dyn ? FB.dynastyNameSet(state, opts.dyn) : null), sexe : sexe, culture : opts.culture, religion : opts.religion, né : opts.born, mort : false, dyn : opts.dyn || null, rôle : opts.role || null, traits : opts.traits || [], compétences : {}, opinion : opts.opinion !== non défini ? opts.opinion : 0, fertilité : FB.rf(0.7, 1.3), station : opts.station !== non défini ? opts.station : null, conjointId : null, pèreId : opts.fatherId || null, motherId : opts.motherId || null, identifiants enfants : [] } ; if (Object.prototype.hasOwnProperty.call(opts, 'byname')) { c.byname = opts.byname; } else if (state && FB.cultureOf(c.culture).dyn === 'patronym' && c.fatherId && state.chars[c.fatherId]) { c.byname = FB.patronym(state.chars[c.fatherId].name, c.sex); } const q = opts.qualité || 0 ; pour (const s de SKILLS) c.skills[s] = Math.max(0, FB.ri(0, 6) + q); if (!opts.traits) { const pool = Object.keys(FBDATA.traits).filter(function (t) { return !FBDATA.traits[t].noRandom; }); const n = opts.traitsN !== non défini ? opts.traitsN : FB.ri(1, 3); pour (soit i = 0; i","hash":"h1-44e902e8"},
